from astropy.io import fitsimport numpy as npimport matplotlib.pyplot as pltimport glob# Folder containing HIRES filesfolder = "data/koa/HIRES/KELT-1/lev1/extracted/HI.20170702.51878"files = sorted(glob.glob(f"{folder}/*.fits.gz"))halpha_rest = 6562.8region_min = 6555region_max = 6570ew_min = 6560.5ew_max = 6564.5found = False# Loop through filesfor file in files:    print(f"\nTrying: {file}")    try:        with fits.open(file) as hdul:            if len(hdul) < 2 or hdul[1].data is None:                continue            table = hdul[1].data                     try:                wave = np.ravel(table['WAVE'])                flux = np.ravel(table['FLUX'])            except KeyError:                raise ValueError("WAVE or FLUX columns not found in the binary table.")               # Clean data        mask = np.isfinite(wave) & np.isfinite(flux)        wave = wave[mask]        flux = flux[mask]        if len(wave) == 0:            continue        # Sort arrays just in case        idx = np.argsort(wave)        wave = wave[idx]        flux = flux[idx]        print(f"  -> Range: {wave.min():.1f} to {wave.max():.1f} Å")               if not np.any((wave > 6560) & (wave < 6565)):            continue        print("  -> Hα found!")              # Extract region        mask_ha = (wave >= region_min) & (wave <= region_max)        wave_ha = wave[mask_ha]        flux_ha = flux[mask_ha]        if len(wave_ha) < 10:            continue        # Normalize (adaptive continuum)        continuum_mask = (wave_ha < 6560) | (wave_ha > 6565)        if len(wave_ha[continuum_mask]) < 5:            print("  -> Not enough continuum points")            continue        coeffs = np.polyfit(wave_ha[continuum_mask], flux_ha[continuum_mask], 1)        continuum = np.polyval(coeffs, wave_ha)        flux_norm = flux_ha / continuum          # Find line center (for shift)        flux_smooth = np.convolve(flux_norm, np.ones(5)/5, mode="same")        i_min = np.argmin(flux_smooth)        halpha_obs = wave_ha[i_min]        delta_lambda = halpha_obs - halpha_rest        print(f"  -> Observed center: {halpha_obs:.3f} Å")        print(f"  -> Shift: {delta_lambda:.3f} Å")        # Shift to rest frame          wave_rest = wave - delta_lambda        mask_rest = (wave_rest >= region_min) & (wave_rest <= region_max)        wave_rest = wave_rest[mask_rest]        flux_rest = flux[mask_rest]        if len(wave_rest) < 10:            continue        # Sort again        idx = np.argsort(wave_rest)        wave_rest = wave_rest[idx]        flux_rest = flux_rest[idx]        # Normalize again        # Select specific, clean line-free windows for the continuum fit        continuum_mask = ((wave_rest > 6556.5) & (wave_rest < 6557.5)) | \                         ((wave_rest > 6567.5) & (wave_rest < 6568.5))        if len(wave_rest[continuum_mask]) < 5:            print("  -> Not enough continuum after shift")            continue        coeffs = np.polyfit(wave_rest[continuum_mask], flux_rest[continuum_mask], 1)        continuum = np.polyval(coeffs, wave_rest)        flux_norm = flux_rest / continuum           # Equivalent Width        ew_mask = (wave_rest >= ew_min) & (wave_rest <= ew_max)        wave_ew = wave_rest[ew_mask]        flux_ew = flux_norm[ew_mask]        if len(wave_ew) < 2:            print("  -> Not enough points for EW")            continue        ew = np.trapz(1 - flux_ew, wave_ew)        print(f"\n Hα Equivalent Width = {ew:.4f} Å")        # Plot        plt.figure(figsize=(8,5))        plt.plot(wave_rest, flux_norm, label="Normalized Spectrum")        plt.axvline(halpha_rest, color="red", linestyle="--", label="Hα 6562.8 Å")        plt.fill_between(wave_ew, flux_ew, 1, alpha=0.3, label="EW region")        plt.xlabel("Wavelength (Å)")        plt.ylabel("Normalized Flux")        plt.title(f"Hα Equivalent Width\n{file.split('/')[-1]}")        plt.legend()        plt.tight_layout()        plt.show()        found = True        break    except Exception as e:        print(f"  -> Error: {e}")if not found:    print("\n No file with usable Hα data found.")